void check(bool v){++checks;if(!v)throw std::runtime_error("test assertion");}
template<class C>void reject(C f){try{f();throw std::runtime_error("missing refusal");}catch(const M::Refusal&){++refusals;}catch(const std::invalid_argument&){++refusals;}}
bool action(const M::Task& t,M::Action a){const auto d=t.actionDescriptors();return std::any_of(d.begin(),d.end(),[a](const auto& x){return x.action==a;});}
template<class C>void ownerReject(M::Task& t,C f){const auto before=t.view();const auto history=t.history().size();reject(f);check(t.view().state==before.state&&t.view().revision==before.revision&&t.view().nextOrdinal==before.nextOrdinal&&t.view().sourceRepairDue==before.sourceRepairDue&&t.history().size()==history);}
void apply(M::Task& t,M::OrderedContactTaskFormAdapter& a,M::Action action){auto f=a.open(action);auto p=F::positiveFor(t,f,action);a.apply(f.token,p);}
void complete(M::Task& t,M::OrderedContactTaskFormAdapter& a){
 for(std::size_t n=0;n<100000;++n){auto v=t.view();currentState=static_cast<int>(v.state);if(v.state==M::State::Traversal){const auto c=t.sourceAtomCue();check(c.ordinal==v.nextOrdinal);const auto ds=t.actionDescriptors();const auto d=std::find_if(ds.begin(),ds.end(),[](const auto& x){return x.action==M::Action::Contact;});check(d!=ds.end()&&d->contact&&d->contact->sourceAtomDescriptor);std::string ins;for(const auto& s:d->instructions)ins+=s+"\n";for(const auto* banned:{"sha256","Build/","Notes/",".json",".pdf"})check(ins.find(banned)==std::string::npos);for(const auto& x:c.atoms){const auto facts=fathom::json::parse(x.sourceFactsJson);if(const auto* accent=facts.find("source_accent"))check(ins.find(accent->boolean()?"Apply the source qualitative root accent here":"outside the source root-accent set")!=std::string::npos);check(x.spelling.empty()||ins.find("written note "+x.spelling)!=std::string::npos);check(x.audible!=false||ins.find("NONAUDIBLE")!=std::string::npos);}const auto& x=c.atoms.front();check(d->contact->sourcePhysicalFret==x.physicalFret&&d->contact->sourceSoundingFret==x.soundingFret&&d->contact->sourceReferenceFret==x.referenceFret&&d->contact->sourceMidi==x.midi&&d->contact->sourcePickAttack==x.picked&&d->contact->sourceAudible==x.audible);t.confirmContact(t.capture(M::Action::Contact),v.nextOrdinal,M::Claim::Yes);}
 else if(v.state==M::State::SourcePhase)apply(t,a,M::Action::SourcePhaseReport);
 else if(v.state==M::State::Release)apply(t,a,M::Action::Release);
 else if(v.state==M::State::Review){if(action(t,M::Action::OppositeStart))apply(t,a,M::Action::OppositeStart);else if(action(t,M::Action::Finish)){apply(t,a,M::Action::Finish);++flows;return;}else if(action(t,M::Action::AdvancePass))apply(t,a,M::Action::AdvancePass);else throw std::runtime_error("review trap");}
 else throw std::runtime_error("normal path trap");}
 throw std::runtime_error("normal path budget");
}
void toPhase(M::Task& t,M::OrderedContactTaskFormAdapter& a,const std::string& id=""){
 for(std::size_t n=0;n<100000;++n){const auto v=t.view();if(v.state==M::State::SourcePhase){const auto p=fathom::json::parse(t.sourceHandle().phaseProgramJson(v.passIndex));if(id.empty()||F::at(F::at(p,"report_phases").array()[v.sourcePhaseIndex],"id")==J(id))return;apply(t,a,M::Action::SourcePhaseReport);}else if(v.state==M::State::Traversal)t.confirmContact(t.capture(M::Action::Contact),v.nextOrdinal,M::Claim::Yes);else if(v.state==M::State::Release)apply(t,a,M::Action::Release);else throw std::runtime_error("phase unreachable");}throw std::runtime_error("phase budget");
}
