 for(const auto& entry:tags){currentKey=entry.second;auto caller=S::definition(currentKey);auto owner=std::make_unique<M::Task>(H::SourceHandle::sourceContact(caller));caller=S::definition(S::keys().back());check(std::string(owner->sourceKey())==currentKey&&owner->sourcePolicy().family==H::Family::SourceContact);auto& t=*owner;M::OrderedContactTaskFormAdapter a(t);auto begin=a.open(M::Action::Begin);auto b=F::positiveFor(t,begin,M::Action::Begin);auto invalid=b;invalid.object()["chosen_bpm"]=J::fromInteger(100);ownerReject(t,[&]{a.apply(begin.token,invalid);});a.apply(begin.token,b);ownerReject(t,[&]{t.deactivateForNavigation();});toPhase(t,a);auto f=a.open(M::Action::SourcePhaseReport);invalid=F::positiveFor(t,f,M::Action::SourcePhaseReport);invalid.object()["foreign"]=true;ownerReject(t,[&]{a.apply(f.token,invalid);});const auto unresolved=F::unresolvedFor(t,f,M::Action::SourcePhaseReport);a.apply(f.token,unresolved);check(t.view().state==M::State::Release&&t.view().sourcePhaseUnresolved);ownerReject(t,[&]{t.release(t.capture(M::Action::Release),M::Claim::Unknown);});ownerReject(t,[&]{t.capture(M::Action::Restart);});apply(t,a,M::Action::Release);const auto count=t.history().size();t.deactivateForNavigation();check(t.history().size()==count&&t.view().sourcePhaseUnresolved);apply(t,a,M::Action::Restart);apply(t,a,M::Action::Begin);complete(t,a);ownerReject(t,[&]{a.apply(f.token,unresolved);});}
 // Each literal repair ID is closed; unknown reports/release/restart cannot erase debt.
 for(const auto& e:levels){const auto p=fathom::json::parse(S::definition(e.second).sourceProgramJson());for(const auto& repair:F::at(p,"repair_options").array()){currentKey=e.second;M::Task t(H::SourceHandle::sourceContactKey(currentKey));M::OrderedContactTaskFormAdapter a(t);apply(t,a,M::Action::Begin);const auto token=t.capture(M::Action::SourceIssueReport);ownerReject(t,[&]{t.reportHarmonicSourceIssue(token,"foreign",J("evidence"));});const auto id=F::at(repair,"id").string();t.reportHarmonicSourceIssue(token,id,J("manual source diagnosis"));check(t.view().state==M::State::Release);apply(t,a,M::Action::Release);apply(t,a,M::Action::Restart);check(t.view().sourceRepairDue==id);ownerReject(t,[&]{t.capture(M::Action::Begin);});auto f=a.open(M::Action::SourceRepairReport);a.apply(f.token,F::unresolvedFor(t,f,M::Action::SourceRepairReport));apply(t,a,M::Action::Release);check(t.view().sourceRepairDue==id);const auto repaired=a.open(M::Action::SourceRepairReport);a.apply(repaired.token,F::positiveFor(t,repaired,M::Action::SourceRepairReport));check(t.view().sourceRepairDue==id&&t.view().state==M::State::Release);ownerReject(t,[&]{t.capture(M::Action::Restart);});apply(t,a,M::Action::Release);check(!t.view().sourceRepairDue);apply(t,a,M::Action::Restart);apply(t,a,M::Action::Begin);t.cancel(t.capture(M::Action::Cancel));apply(t,a,M::Action::Release);}}
 // Persistent mandatory foundation reduction and source36's genuine OR branch.
 for(const int level:{12,36})for(const bool isolate:{false,true}){if(level==12&&isolate)continue;currentKey=levels.at(level);M::Task t(H::SourceHandle::sourceContactKey(currentKey));M::OrderedContactTaskFormAdapter a(t);apply(t,a,M::Action::Begin);toPhase(t,a,level==12?"literal_source_route_quality":"source_module_quality");auto f=a.open(M::Action::SourcePhaseReport);auto bad=F::positiveFor(t,f,M::Action::SourcePhaseReport);bad.object()["source_errors"]=J::fromInteger(2);bad.object()["source_issue"]="error";a.apply(f.token,bad);check(t.view().sourceRepairDue&&t.view().tempoReductionDue);apply(t,a,M::Action::Release);t.deactivateForNavigation();apply(t,a,M::Action::Restart);ownerReject(t,[&]{t.capture(M::Action::Begin);});const auto repaired=a.open(M::Action::SourceRepairReport);auto good=F::positiveFor(t,repaired,M::Action::SourceRepairReport);if(isolate){good.object()["repair_choice"]="isolate_one_source_unit";good.object()["isolated_one_printed_source_unit"]="reported_met";good.object()["previous_reported_bpm"]=nullptr;good.object()["reported_new_bpm"]=nullptr;good.object()["drop_bpm"]=nullptr;}a.apply(repaired.token,good);check(t.view().sourceRepairDue.has_value());apply(t,a,M::Action::Release);check(!t.view().sourceRepairDue&&!t.view().tempoReductionDue);apply(t,a,M::Action::Restart);apply(t,a,M::Action::Begin);complete(t,a);check(t.view().reportedBpm==(isolate?100:96));}
 // Ear response is committed before source self-check and compared to that owned response.
 const auto ear=std::find_if(S::keys().begin(),S::keys().end(),[](const auto& k){const auto p=fathom::json::parse(S::definition(k).sourceProgramJson());return F::at(F::at(p,"report_phases").array()[0],"id")==J("source_ear_response");});check(ear!=S::keys().end());currentKey=*ear;M::Task t(H::SourceHandle::sourceContactKey(*ear));M::OrderedContactTaskFormAdapter a(t);apply(t,a,M::Action::Begin);toPhase(t,a,"source_ear_response");auto f=a.open(M::Action::SourcePhaseReport);auto wrong=F::positiveFor(t,f,M::Action::SourcePhaseReport);wrong.object()["heard_center"]=wrong.object()["heard_center"]==J("A-centered")?J("F#-centered"):J("A-centered");a.apply(f.token,wrong);check(t.view().state==M::State::Release);ownerReject(t,[&]{t.capture(M::Action::SourcePhaseReport);});apply(t,a,M::Action::Release);apply(t,a,M::Action::SourcePhaseReport);check(t.view().sourcePhaseUnresolved&&t.view().state==M::State::Release);apply(t,a,M::Action::Release);apply(t,a,M::Action::Restart);apply(t,a,M::Action::Begin);complete(t,a);
 auto owner=[](){auto temporary=H::SourceHandle::sourceContactKey(S::keys()[0]);return std::make_unique<M::Task>(temporary);}();M::Task foreign(H::SourceHandle::sourceContactKey(S::keys()[0]));const auto foreignToken=foreign.capture(M::Action::Begin);ownerReject(*owner,[&]{owner->begin(foreignToken,{M::Branch::PrintedPassProgression,M::Rhythm::Unspecified,fathom::tasks::ordered_contacts::Start::Unspecified});});
 std::cout<<"{\"material_result\":\"PASS\",\"dispatch_profiles\":"<<tags.size()<<",\"source_levels\":"<<levels.size()<<",\"assertions\":"<<checks<<",\"refusals\":"<<refusals<<",\"complete_recovery_flows\":"<<flows<<"}\n";
