int main(int argc,char** argv){try{
 if(argc==2&&std::string(argv[1])=="--quality-material"){qualityMaterial();return 0;}
 if(argc==2&&std::string(argv[1])=="--material"){material();return 0;}
 const auto started=std::chrono::steady_clock::now();check(S::keys().size()==465);std::size_t simultaneous=0,unpitched=0,references=0,unpicked=0;
 std::size_t visited=0;
 for(const auto& key:S::keys()){
  if(argc==2&&std::string(argv[1])=="--affected-quality"){const auto p=fathom::json::parse(S::definition(key).sourceProgramJson());const auto& phases=F::at(p,"report_phases").array();if(std::none_of(phases.begin(),phases.end(),[](const auto& phase){return F::at(F::at(phase,"report_schema"),"properties").find("source_errors");}))continue;}
  else if(argc==2&&key!=argv[1])continue;currentKey=key;++visited;
  const auto d=S::definition(key);auto caller=d;const auto h=H::SourceHandle::sourceContact(caller);check(h.sourceKey()==key);check(h.family()==H::Family::SourceContact);reject([&]{h.projection(H::Start::Down);});
  for(std::size_t r=0;r<d.routeCount();++r){check(d.selectedMetricEnd(r)==h.phaseMetricEnd(r));auto starts=d.savedPickVariants(r);if(starts.empty())starts.push_back(S::PickVariant::Unspecified);for(const auto s:starts)for(std::size_t n=1;n<=d.contactCount(r);++n){auto c=d.contact(n,s,r);d.requireSourceParity(c,s);check(c.ordinal==n&&c.sourceKey==key);simultaneous+=c.simultaneous;for(const auto& a:c.atoms){++atoms;unpitched+=!a.midi;references+=a.audible==false;unpicked+=a.picked==false;check(!a.midi||(*a.midi>=0&&*a.midi<=127));}auto bad=c;bad.sourceKey="foreign";reject([&]{d.requireSourceParity(bad,s);});}reject([&]{d.contact(0,starts[0],r);});reject([&]{d.contact(d.contactCount(r)+1,starts[0],r);});}
  M::Task task(h);M::OrderedContactTaskFormAdapter adapter(task);apply(task,adapter,M::Action::Begin);complete(task,adapter);check(!task.view().coverage.wholeChildAccepted&&!task.view().coverage.performanceObserved&&!task.view().coverage.runtimeAdmitted);
 }
 std::cout<<"{\"result\":\"PASS\",\"keys\":"<<visited<<",\"assertions\":"<<checks<<",\"refusals\":"<<refusals<<",\"atom_variant_comparisons\":"<<atoms<<",\"flows\":"<<flows<<",\"simultaneous\":"<<simultaneous<<",\"unknown_pitch\":"<<unpitched<<",\"nonaudible\":"<<references<<",\"unpicked\":"<<unpicked<<",\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count()<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<" key="<<currentKey<<" state="<<currentState<<" checks="<<checks<<" flows="<<flows<<"\n";return 1;}}
